/** The panels' surface: Popover's bg, border, radius and lg shadow. */
const surfaceClass = cn(
  'sa:rounded-xl sa:border sa:border-border-subtle sa:bg-bg-popover',
  'sa:[box-shadow:0_4px_6px_-4px_var(--sa-effect-shadow-float-contact),0_10px_15px_-3px_var(--sa-effect-shadow-float-contact),0_2px_20px_0_var(--sa-effect-shadow-float)]',
)
/**
 * A panel with presets wraps (see PresetList). In a popover it is held to the room Radix
 * measures beside the trigger, so it wraps there too rather than running off a phone's screen.
 */
const presetPanelClass = 'sa:flex sa:w-fit sa:max-w-(--radix-popover-content-available-width) sa:flex-wrap sa:overflow-hidden'
const popClass = cn(
  'sa:z-50 sa:outline-none',
  'sa:origin-(--radix-popover-content-transform-origin) sa:data-[state=open]:animate-[satin-enter_var(--sa-duration-base)_var(--sa-ease-out)]',
)

interface FieldBits {
  label?: React.ReactNode
  hint?: React.ReactNode
  error?: React.ReactNode | boolean
  /** Shown while nothing is picked. Defaults to the `pickDate` / `pickDates` label. */
  placeholder?: string
  disabled?: boolean
  id?: string
  size?: 'sm' | 'md' | 'lg'
  /** Classes for the outer wrapper (label + field + hint). `className` styles the field. */
  wrapperClassName?: string
  className?: string
}

function Trigger({ text, placeholder, chrome, size, open, className, ...props }: { text: string; placeholder: string; chrome: ReturnType<typeof useFieldChrome>; size: 'sm' | 'md' | 'lg'; open: boolean; className?: string } & React.ComponentProps<'button'>) {
  return (
    <button
      type="button"
      id={chrome.controlId}
      data-slot="date-picker-trigger"
      data-size={size}
      data-filled={text ? true : undefined}
      data-invalid={chrome.invalid || undefined}
      data-disabled={chrome.disabled || undefined}
      data-state={open ? 'open' : 'closed'}
      disabled={chrome.disabled}
      aria-invalid={chrome.invalid || undefined}
      aria-describedby={chrome.describedBy}
      className={cn('satin-field sa:cursor-pointer sa:text-start', className)}
      {...props}
    >
      <span className="satin-field-icon" aria-hidden>
        <CalendarIcon />
      </span>
      <span className={cn('sa:min-w-0 sa:flex-1 sa:truncate', text ? 'sa:text-text-default' : 'sa:text-text-muted')}>{text || placeholder}</span>
      <span className="satin-field-icon" aria-hidden>
        <NavArrowDown className={cn('sa:transition-transform sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)', open && 'sa:rotate-180')} />
      </span>
    </button>
  )
}

export interface DatePickerPanelProps extends Omit<React.ComponentProps<'div'>, 'defaultValue' | 'children'> {
  value?: Date | null
  /** A day picked in the calendar or from the presets. */
  onValueChange?: (value: Date) => void
  min?: Date
  max?: Date
  today?: Date
  /** As on Calendar: days that can't be picked, besides those outside min/max. */
  isDisabled?: CalendarProps['isDisabled']
  /** As on Calendar: draws each day; return a `CalendarDay`. */
  renderDay?: CalendarProps['renderDay']
  /** Shortcuts listed before the calendar: `[datePresets.today, datePresets.tomorrow]`. Picking one moves the calendar to its month. */
  presets?: DatePreset<Date>[]
  /** The week's first day, 0 for Sunday. Defaults to the `dateLocale` label's. */
  weekStartsOn?: WeekDay
  className?: string
}

/** The date picker's panel on its own, in place: the popover surface with the Calendar, month and year to pick, and the presets. Other props, `ref` included, go to the surface. */
export function DatePickerPanel({ value, onValueChange, min, max, today, isDisabled, renderDay, presets, weekStartsOn, className, ...props }: DatePickerPanelProps) {
  const weekStart = useWeekStart(weekStartsOn)
  const [month, setMonth] = React.useState(() => addMonths(value ?? today ?? todayDate(), 0))
  const items = usePresetItems(presets, today, weekStart, min, max, isDisabled)
  const calendar = (
    <Calendar header="picker" value={value} onValueChange={onValueChange} month={month} onMonthChange={setMonth} min={min} max={max} today={today} isDisabled={isDisabled} renderDay={renderDay} weekStartsOn={weekStart} />
  )
  if (!items.length)
    return (
      <div {...props} data-slot="date-picker-panel" className={cn(surfaceClass, 'sa:w-fit sa:p-3', className)}>
        {calendar}
      </div>
    )
  return (
    <div {...props} data-slot="date-picker-panel" className={cn(surfaceClass, presetPanelClass, className)}>
      <PresetList
        items={items}
        active={items.findIndex((p) => !p.disabled && sameDay(p.from, value))}
        onPick={(p) => {
          setMonth(addMonths(p.from, 0))
          onValueChange?.(p.from)
        }}
      />
      <div className="sa:flex sa:grow sa:justify-center sa:p-3">{calendar}</div>
    </div>
  )
}

type TriggerAttributes = Omit<React.ComponentProps<'button'>, keyof FieldBits | 'value' | 'defaultValue' | 'type' | 'children'>

export interface DatePickerProps extends FieldBits, TriggerAttributes {
  value?: Date | null
  defaultValue?: Date | null
  onValueChange?: (value: Date) => void
  min?: Date
  max?: Date
  today?: Date
  /** As on Calendar: days that can't be picked, besides those outside min/max. */
  isDisabled?: CalendarProps['isDisabled']
  /** As on Calendar: draws each day; return a `CalendarDay`. */
  renderDay?: CalendarProps['renderDay']
  /** Shortcuts listed before the calendar: `[datePresets.today, datePresets.tomorrow]`. Picking one picks its day and closes. */
  presets?: DatePreset<Date>[]
  /** The week's first day, 0 for Sunday. Defaults to the `dateLocale` label's. */
  weekStartsOn?: WeekDay
  /** Portal target. */
  container?: HTMLElement | null
}

/**
 * A date field: the kit Input's skin with a calendar icon; the Calendar opens 4px below, with month and year to pick.
 * Other props, `ref` included, go to the trigger button.
 */
export function DatePicker({
  value: valueProp,
  defaultValue = null,
  onValueChange,
  min,
  max,
  today,
  isDisabled,
  renderDay,
  presets,
  weekStartsOn,
  label,
  hint,
  error,
  placeholder,
  disabled,
  id,
  size = 'md',
  container,
  wrapperClassName,
  className,
  'aria-describedby': describedBy,
  ...props
}: DatePickerProps) {
  const chrome = useFieldChrome({ id, disabled, error, hint })
  const labels = useSatinLabels()
  const [inner, setInner] = React.useState<Date | null>(defaultValue)
  const value = valueProp !== undefined ? valueProp : inner
  const [open, setOpen] = React.useState(false)
  return (
    <FieldChrome label={label} chrome={chrome} className={wrapperClassName}>
      <PopoverPrimitive.Root open={open} onOpenChange={setOpen}>
        <PopoverPrimitive.Trigger asChild {...props}>
          <Trigger
            text={value ? formatDate(value, labels.dateLocale) : ''}
            placeholder={placeholder ?? labels.pickDate}
            chrome={chrome}
            size={size}
            open={open}
            aria-describedby={[describedBy, chrome.describedBy].filter(Boolean).join(' ') || undefined}
            className={className}
          />
        </PopoverPrimitive.Trigger>
        <PopoverPrimitive.Portal container={container}>
          <PopoverPrimitive.Content
            data-slot="date-picker"
            align="start"
            sideOffset={4}
            collisionPadding={8}
            // The panel is a dialog: it takes the field's name (its label, or its aria-label).
            aria-labelledby={label ? `${chrome.controlId}-label` : undefined}
            aria-label={label ? undefined : (props['aria-label'] ?? placeholder ?? labels.pickDate)}
            className={popClass}
          >
            <DatePickerPanel
              value={value}
              min={min}
              max={max}
              today={today}
              isDisabled={isDisabled}
              renderDay={renderDay}
              presets={presets}
              weekStartsOn={weekStartsOn}
              onValueChange={(d) => {
                if (valueProp === undefined) setInner(d)
                onValueChange?.(d)
                setOpen(false)
              }}
            />
          </PopoverPrimitive.Content>
        </PopoverPrimitive.Portal>
      </PopoverPrimitive.Root>
    </FieldChrome>
  )
}

export interface DateRangePickerProps extends FieldBits, TriggerAttributes {
  value?: DateRange
  defaultValue?: DateRange
  /** Called on Apply. */
  onValueChange?: (value: DateRange) => void
  min?: Date
  max?: Date
  today?: Date
  /** As on Calendar: days that can't be picked, besides those outside min/max. */
  isDisabled?: CalendarProps['isDisabled']
  /** As on Calendar: draws each day; return a `CalendarDay`. */
  renderDay?: CalendarProps['renderDay']
  /** Shortcuts listed before the calendar: `[datePresets.last7Days, datePresets.last30Days]`. Picking one shows its range, which waits for Apply like any other. */
  presets?: DatePreset<DateRange | Date>[]
  /** The week's first day, 0 for Sunday. Defaults to the `dateLocale` label's. */
  weekStartsOn?: WeekDay
  /** Defaults to the `apply` label. */
  applyLabel?: string
  /** Defaults to the `cancel` label. */
  cancelLabel?: string
  container?: HTMLElement | null
}

/**
 * A range field: two months, Cancel and Apply in the footer. Picks wait for Apply. Picking an
 * end before the start swaps them. Other props, `ref` included, go to the trigger button.
 */
export function DateRangePicker({
  value: valueProp,
  defaultValue = { from: null, to: null },
  onValueChange,
  min,
  max,
  today,
  isDisabled,
  renderDay,
  presets,
  weekStartsOn,
  label,
  hint,
  error,
  placeholder,
  disabled,
  id,
  size = 'md',
  applyLabel,
  cancelLabel,
  container,
  wrapperClassName,
  className,
  'aria-describedby': describedBy,
  ...props
}: DateRangePickerProps) {
  const chrome = useFieldChrome({ id, disabled, error, hint })
  const labels = useSatinLabels()
  const [inner, setInner] = React.useState<DateRange>(defaultValue)
  const value = valueProp ?? inner
  const [open, setOpen] = React.useState(false)
  const commit = (r: DateRange) => {
    if (!valueProp) setInner(r)
    onValueChange?.(r)
    setOpen(false)
  }
  return (
    <FieldChrome label={label} chrome={chrome} className={wrapperClassName}>
      <PopoverPrimitive.Root open={open} onOpenChange={setOpen}>
        <PopoverPrimitive.Trigger asChild {...props}>
          <Trigger
            text={formatRange(value, labels.dateLocale)}
            placeholder={placeholder ?? labels.pickDates}
            chrome={chrome}
            size={size}
            open={open}
            aria-describedby={[describedBy, chrome.describedBy].filter(Boolean).join(' ') || undefined}
            className={className}
          />
        </PopoverPrimitive.Trigger>
        <PopoverPrimitive.Portal container={container}>
          <PopoverPrimitive.Content
            data-slot="date-range-picker"
            align="start"
            sideOffset={4}
            collisionPadding={8}
            aria-labelledby={label ? `${chrome.controlId}-label` : undefined}
            aria-label={label ? undefined : (props['aria-label'] ?? placeholder ?? labels.pickDates)}
            className={popClass}
          >
            <DateRangePickerPanel
              value={value}
              min={min}
              max={max}
              today={today}
              isDisabled={isDisabled}
              renderDay={renderDay}
              presets={presets}
              weekStartsOn={weekStartsOn}
              applyLabel={applyLabel}
              cancelLabel={cancelLabel}
              onApply={commit}
              onCancel={() => setOpen(false)}
            />
          </PopoverPrimitive.Content>
        </PopoverPrimitive.Portal>
      </PopoverPrimitive.Root>
    </FieldChrome>
  )
}

export interface DateRangePickerPanelProps extends Omit<React.ComponentProps<'div'>, 'defaultValue' | 'children'> {
  /** The range the panel starts from; picks stay in the panel until Apply. */
  value?: DateRange
  /** Apply. */
  onApply?: (value: DateRange) => void
  onCancel?: () => void
  min?: Date
  max?: Date
  today?: Date
  /** As on Calendar: days that can't be picked, besides those outside min/max. */
  isDisabled?: CalendarProps['isDisabled']
  /** As on Calendar: draws each day; return a `CalendarDay`. */
  renderDay?: CalendarProps['renderDay']
  /** Shortcuts listed before the calendar. Picking one shows its range; a range picked by hand leaves none selected. */
  presets?: DatePreset<DateRange | Date>[]
  /** The week's first day, 0 for Sunday. Defaults to the `dateLocale` label's. */
  weekStartsOn?: WeekDay
  /** Defaults to the `apply` label. */
  applyLabel?: string
  /** Defaults to the `cancel` label. */
  cancelLabel?: string
  className?: string
}

/** The range picker's panel on its own, in place: the presets, two months, Cancel and Apply. Other props, `ref` included, go to the surface. */
export function DateRangePickerPanel({
  value = { from: null, to: null },
  onApply,
  onCancel,
  min,
  max,
  today,
  isDisabled,
  renderDay,
  presets,
  weekStartsOn,
  applyLabel,
  cancelLabel,
  className,
  ...props
}: DateRangePickerPanelProps) {
  const labels = useSatinLabels()
  const weekStart = useWeekStart(weekStartsOn)
  const [draft, setDraft] = React.useState<DateRange>(value)
  const [month, setMonth] = React.useState(() => addMonths(value.from ?? today ?? todayDate(), 0))
  const items = usePresetItems(presets, today, weekStart, min, max)
  const body = (
    <>
      <div className="sa:p-3">
        <Calendar mode="range" months={2} range={draft} onRangeChange={setDraft} month={month} onMonthChange={setMonth} min={min} max={max} today={today} isDisabled={isDisabled} renderDay={renderDay} weekStartsOn={weekStart} />
      </div>
      <div className="sa:flex sa:items-center sa:justify-end sa:gap-2 sa:border-t sa:border-border-subtle sa:px-3 sa:py-2">
        <Button variant="secondary" onClick={() => { setDraft(value); onCancel?.() }}>
          {cancelLabel ?? labels.cancel}
        </Button>
        <Button disabled={!draft.from || !draft.to} onClick={() => onApply?.(draft)}>
          {applyLabel ?? labels.apply}
        </Button>
      </div>
    </>
  )
  if (!items.length)
    return (
      <div {...props} data-slot="date-range-picker-panel" className={cn(surfaceClass, 'sa:flex sa:w-fit sa:shrink-0 sa:flex-col sa:overflow-hidden', className)}>
        {body}
      </div>
    )
  return (
    <div {...props} data-slot="date-range-picker-panel" className={cn(surfaceClass, presetPanelClass, 'sa:shrink-0', className)}>
      <PresetList
        items={items}
        active={items.findIndex((p) => !p.disabled && sameDay(p.from, draft.from) && sameDay(p.to, draft.to))}
        onPick={(p) => {
          setDraft({ from: p.from, to: p.to })
          setMonth(addMonths(p.from, 0))
        }}
      />
      <div className="sa:flex sa:grow sa:flex-col sa:[&>:first-child]:self-center">{body}</div>
    </div>
  )
}
